import type { ImgHTMLAttributes, Ref } from 'react';
import { darkSourceMedia, useForcedTheme } from '../../ui/theme/theme';

/** The dark-theme file of a raster: same geometry, the blue turned to the dark accent. */
export interface DarkVariant {
  src: string;
  srcSet?: string;
}

interface ThemeImageProps extends ImgHTMLAttributes<HTMLImageElement> {
  /** Generated by scripts/generate-theme-variants.mjs, never drawn by hand.
   *  Without it (and without `avif`) this is a plain <img>. */
  dark?: DarkVariant;
  /** An AVIF file or srcset (sharing `sizes`) of the light image, preferred where supported. */
  avif?: string;
  pictureClassName?: string;
  pictureRef?: Ref<HTMLPictureElement>;
}

/**
 * One raster, both themes (DESIGN.md "Palette and material"). The browser picks
 * the source before fetching, so the dark variant needs no JavaScript, never
 * flashes and the prerendered HTML is identical for every visitor. A theme
 * forced from the header turns the source's media into `all` / `not all`
 * after hydration (components/ui/theme), and the browser re-selects. The
 * <picture> wrapper is inline and unpositioned: classes stay on the <img>, so
 * existing layout rules keep applying.
 */
export function ThemeImage({ dark, avif, pictureClassName, pictureRef, sizes, ...image }: ThemeImageProps) {
  const forced = useForcedTheme();
  if (!dark && !avif) return <img sizes={sizes} {...image} />;
  return (
    <picture className={pictureClassName} ref={pictureRef}>
      {dark && <source media={darkSourceMedia(forced)} srcSet={dark.srcSet ?? dark.src} sizes={sizes} />}
      {avif && <source type="image/avif" srcSet={avif} sizes={sizes} />}
      <img sizes={sizes} {...image} />
    </picture>
  );
}

export default ThemeImage;
